export const wsScenes=['opening','before','friction','mail','calendar','meet','collaborate','work','gemini','followup','final'];
export const initialWorkspace=()=>({scene:'opening',thread:initialThread(),before:0,availability:false,slot:null,team:false,meetLink:false,attachment:false,event:false,meetingStarted:false,notes:false,channel:null,space:false,spaceTab:'Discussion',file:null,edits:0,doc:false,ai:false,aiTab:'REQUIREMENTS',draft:false,network:false,lesson:0,calendarTry:'Create event',practice:null,quiz:0,answer:null});
export function wsReady(s){switch(s.scene){case 'opening':case 'before':case 'friction':case 'mail':return true;case 'calendar':return s.event;case 'meet':return s.notes;case 'collaborate':return s.space&&s.channel==='space';case 'work':return s.edits===2&&s.doc;case 'gemini':return s.ai;case 'followup':return s.draft;default:return false;}}
export function wsNextHint(s){return {calendar:'Choose a time, add the team, Meet and assessment, then create the event.',meet:'Start the meeting and capture the meeting context.',collaborate:'Create the project Space to carry the context forward.',work:'Add both assessment inputs and update the Proposal Draft.',gemini:'Summarize the selected project context.',followup:'Create the follow-up draft before the final reveal.'}[s.scene]||'';}
export function workspaceTransition(state,action,value){const threadResult=threadTransition(state,action,value);if(threadResult)return threadResult;const s={...state};switch(action){
 case 'next':if(s.scene==='final'&&!s.network){s.network=true;break;}if(!wsReady(s))return s;if(s.scene==='before'&&s.before<8)s.before++;else s.scene=wsScenes[Math.min(wsScenes.length-1,wsScenes.indexOf(s.scene)+1)];break;
 case 'prev':if(s.scene==='final'&&s.network){s.network=false;break;}if(s.scene==='before'&&s.before>0)s.before--;else s.scene=wsScenes[Math.max(0,wsScenes.indexOf(s.scene)-1)];break;
 case 'find-time':if(s.scene==='calendar')s.availability=true;break;
 case 'slot':if(s.scene==='calendar'&&s.availability&&['Tue 10:30','Wed 14:00'].includes(value)){s.slot=value;s.event=false;}break;
 case 'invite':if(s.scene==='calendar')s.team=true;break;
 case 'meet-link':if(s.scene==='calendar')s.meetLink=true;break;
 case 'attach':if(s.scene==='calendar')s.attachment=true;break;
 case 'create-event':if(s.scene==='calendar'&&s.slot&&s.team&&s.meetLink&&s.attachment)s.event=true;break;
 case 'start-meet':if(s.scene==='meet'&&s.event)s.meetingStarted=true;break;
 case 'notes':if(s.scene==='meet'&&s.meetingStarted)s.notes=true;break;
 case 'chat':if(s.scene==='collaborate')s.channel='chat';break;
 case 'space':if(s.scene==='collaborate'){s.channel='space';s.space=true;}break;
 case 'space-tab':if(['Discussion','Meeting context','Files','Links','Updates'].includes(value))s.spaceTab=value;break;
 case 'file':if(s.scene==='work'&&['Architecture.pdf','Assessment.xlsx','Meeting Notes','Proposal Draft'].includes(value))s.file=value;break;
 case 'edit-sheet':if(s.scene==='work'&&s.file==='Assessment.xlsx')s.edits=Math.min(2,s.edits+1);break;
 case 'edit-doc':if(s.scene==='work'&&s.file==='Proposal Draft')s.doc=true;break;
 case 'ai':if(s.scene==='gemini'&&s.notes&&s.edits===2&&s.doc)s.ai=true;break;
 case 'ai-tab':if(['REQUIREMENTS','RISKS','OPEN QUESTIONS','NEXT ACTIONS'].includes(value))s.aiTab=value;break;
 case 'draft':if(s.scene==='followup'&&s.ai)s.draft=true;break;
 case 'network':if(s.scene==='final')s.network=true;break;
 case 'lesson':s.lesson=Math.max(0,Math.min(workspaceLessons.length-1,Math.floor(Number(value)||0)));s.practice=null;break;
 case 'calendar-try':s.calendarTry=value;break;
 case 'practice':s.practice=value;break;
 case 'classify':if(value==='CHAT'||value==='SPACE')s.answer=value;break;
 case 'quiz-next':if(s.answer){s.quiz=(s.quiz+1)%5;s.answer=null;}break;
 case 'reset':return initialWorkspace();
 }return s;}
