export function workspaceGuide(s){if(s.scene==='calendar')return {ask:'How do teams arrange meetings today?',listen:'Manual scheduling · WhatsApp coordination · Calendar conflicts · Separate meeting links',probe:'Whose availability is hardest to confirm?',next:'Map one team’s scheduling and invitation workflow.'};if(s.scene==='collaborate')return {ask:'Where does project communication normally happen?',listen:'WhatsApp groups · Lost context · New members cannot follow history · Files scattered across conversations',probe:'How does a new project member find the latest decisions?',next:'Pilot a project Space with owners, membership and file access agreed.'};if(s.scene==='work')return {ask:'Where do teams normally store and share working files?',listen:'Personal storage · Email attachments · Duplicate versions · Unclear ownership',probe:'How do you identify the working version and its owner?',next:'Review one project’s files, ownership and sharing workflow.'};if(['meet','gemini','followup'].includes(s.scene))return {ask:'What normally happens to meeting notes and action items?',listen:'Manual notes · No action tracking · Information lost after meetings',probe:'Who reviews the notes and turns them into the next action?',next:'Explore one meeting-to-follow-up workflow; confirm Gemini entitlement and settings.'};return {ask:'Where does context get lost between a request and the next action?',listen:'Repeated handoffs · Searching for files · Manual coordination',probe:'Which handoff causes the most rework for your team?',next:'Choose one everyday workflow to assess with the team.'};}

